package com.auditlog.api

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import java.time.Instant
import java.util.concurrent.ConcurrentHashMap
import javax.script.ScriptEngineManager

data class AuditEntry(
    val timestamp: String,
    val actor: String,
    val action: String,
    val resource: String,
    val metadata: Map<String, String> = emptyMap()
)

object AuditStore {
    private val entries = mutableListOf<AuditEntry>()
    fun add(entry: AuditEntry) { synchronized(entries) { entries.add(entry) } }
    fun getAll(): List<AuditEntry> = synchronized(entries) { entries.toList() }
    fun query(filter: (AuditEntry) -> Boolean) = getAll().filter(filter)
}

object TemplateEngine {
    private val templateCache = ConcurrentHashMap<String, String>()

    fun registerTemplate(name: String, content: String) {
        templateCache[name] = content
    }

    fun render(templateName: String, context: Map<String, Any>): String {
        val template = templateCache[templateName]
            ?: return "Template not found: $templateName"
        return interpolate(template, context)
    }

    private fun interpolate(template: String, context: Map<String, Any>): String {
        var result = template
        // Simple variable substitution: {{varName}}
        val varPattern = Regex("\\{\\{\\s*(\\w+)\\s*\\}\\}")
        result = varPattern.replace(result) { match ->
            val key = match.groupValues[1]
            context[key]?.toString() ?: ""
        }
        // Expression evaluation: {{% expr %}}
        val exprPattern = Regex("\\{\\{%\\s*(.+?)\\s*%\\}\\}")
        result = exprPattern.replace(result) { match ->
            val expr = match.groupValues[1]
            evaluateExpression(expr, context)
        }
        return result
    }

    private fun evaluateExpression(expr: String, context: Map<String, Any>): String {
        return try {
            val engine = ScriptEngineManager().getEngineByExtension("kts")
                ?: ScriptEngineManager().getEngineByName("js")
                ?: return "[eval error]"
            context.forEach { (k, v) -> engine.put(k, v) }
            engine.eval(expr)?.toString() ?: ""
        } catch (e: Exception) {
            "[error: ${e.message}]"
        }
    }
}

class ReportFormatter {
    companion object {
        private val SAFE_REPORT_FIELDS = setOf("actor", "action", "resource", "timestamp", "count")

        fun formatAuditReport(entries: List<AuditEntry>, reportTemplate: String): String {
            // Build summary context from entries
            val context = buildReportContext(entries)
            // Register the user-provided template transiently
            val tempName = "report_${System.nanoTime()}"
            TemplateEngine.registerTemplate(tempName, reportTemplate)
            return TemplateEngine.render(tempName, context)
        }

        private fun buildReportContext(entries: List<AuditEntry>): Map<String, Any> {
            val ctx = mutableMapOf<String, Any>()
            ctx["count"] = entries.size
            ctx["timestamp"] = Instant.now().toString()
            if (entries.isNotEmpty()) {
                ctx["actor"] = entries.last().actor
                ctx["action"] = entries.last().action
                ctx["resource"] = entries.last().resource
            }
            return ctx
        }

        fun validateTemplate(template: String): Boolean {
            // Only allow simple variable references from safe fields
            val varPattern = Regex("\\{\\{\\s*(\\w+)\\s*\\}\\}")
            val vars = varPattern.findAll(template).map { it.groupValues[1] }.toList()
            return vars.all { it in SAFE_REPORT_FIELDS }
        }
    }
}

fun Application.configureRouting() {
    routing {
        post("/api/audit") {
            val params = call.receiveParameters()
            val entry = AuditEntry(
                timestamp = Instant.now().toString(),
                actor = params["actor"] ?: "unknown",
                action = params["action"] ?: "unknown",
                resource = params["resource"] ?: "unknown"
            )
            AuditStore.add(entry)
            call.respondText("OK", status = HttpStatusCode.Created)
        }

        get("/api/audit") {
            val entries = AuditStore.getAll()
            val response = entries.joinToString("\n") {
                "[${it.timestamp}] ${it.actor} ${it.action} ${it.resource}"
            }
            call.respondText(response)
        }

        post("/api/audit/report") {
            val params = call.receiveParameters()
            val template = params["template"] ?: "Report: {{count}} entries as of {{timestamp}}"
            val entries = AuditStore.getAll()

            // Validation checks simple variable references
            if (!ReportFormatter.validateTemplate(template)) {
                call.respondText("Invalid template: only safe fields allowed",
                    status = HttpStatusCode.BadRequest)
                return@post
            }

            val report = ReportFormatter.formatAuditReport(entries, template)
            call.respondText(report, ContentType.Text.Plain)
        }
    }
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        configureRouting()
    }.start(wait = true)
}
